// function truncate(str, maxLen) mein string aur max length do
// Agar string nahi: ""
// Agar length <= maxLen: original string
// Warna truncated string with "..." do

solution:
function truncate(str, maxLen) {
  if (typeof str !== "string") return ""
  if (str.length <= maxLen) return str
  return str.slice(0, maxLen) + "..."
}
